import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第四十一章 消除争斗和愤怒的烦恼和痛苦","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/41第四十一章 消除争斗和愤怒的烦恼和痛苦.md","filePath":"meditation/巴利文大藏经/41第四十一章 消除争斗和愤怒的烦恼和痛苦.md"}'),o={name:"meditation/巴利文大藏经/41第四十一章 消除争斗和愤怒的烦恼和痛苦.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第四十一章-消除争斗和愤怒的烦恼和痛苦" tabindex="-1">第四十一章 消除争斗和愤怒的烦恼和痛苦 <a class="header-anchor" href="#第四十一章-消除争斗和愤怒的烦恼和痛苦" aria-label="Permalink to &quot;第四十一章 消除争斗和愤怒的烦恼和痛苦&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应16经/反对者经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，舍卫城里有个喜欢与人争辩的婆罗门，他心里想：「我现在去见出家人乔达摩（佛陀），他说什么，我都反对他；他说什么，我都说他胡说八道、信口开河，不与他讲道理，他一定会气急败坏、暴跳如雷的，这样我就赢了。」</p><p>那个时候，佛陀正在户外来回的走动，这个婆罗门就走到佛陀的身边，他对佛陀说：“出家人，你能为我说一些法吗？”</p><p>佛陀看见这个婆罗门后，就知道他想要干什么了，就对他说：“如来说的法，对于那些无理取闹、混淆是非、颠倒黑白，喜欢反对人，喜欢与人争辩的人来说，那是不容易被他们明白和理解的，因为他们根本就不会认真的去听如来说法，他们连如来说的是什么都不清楚。他们的内心被愤怒和狂热的激情所污染，哪里还会去认真听如来说法，他们听法的目的，不过是想借听法的机会来捣乱而已，无法获得正法的利益。只有他们将内心的愤怒除灭、消解后，只有他们能够控制和调节好内心不被极端的情绪所影响的时候，只有他们对如来生起坚定信心的时候，才能除去他们内心的烦恼障碍，才能除去他们听法的障碍，让他们安心清净的听如来说法，这样他们才能真正明白如来说的到底是什么法。无理取闹、混淆是非、颠倒黑白，喜欢反对人，喜欢与人争辩的人他们其实在与自己作对，因为他们无法由此得闻正法，他们被内心生出来的这些争斗和愤怒的烦恼和痛苦束缚捆绑，不得解脱。他们患上了争斗和愤怒的疾病，他们被争斗和愤怒的病痛缠绕还不知道要赶紧治疗，真是可怜的人。然而如来的正法就是治疗他们病症的药，他们如果不认真的听如来说法，如果不服下如来给他们开出来的心药，他们是无法治愈争斗和愤怒的疾病的。</p><p>婆罗门，如来给你开出来的心药，你准备服用吗？”</p><p>这时，佛陀说偈言：</p><p>「心污嗔恚多，何亦好反对。</p><p>如是善说法，亦甚难得知。</p><p>唯有灭嗔恚，除去无信乐。</p><p>心之障碍者，始知善说法。」</p><p>佛陀说法后，这个婆罗门立刻就跪在地上顶礼佛陀，他对佛陀说：“世尊，我从来都没有想过，我反对别人，与别人争辩、争斗，内心生起的愤怒和激动的情绪是一种疾病。我刚才仔细的想了一下，我确实被这些行为和情绪所控制和影响，我被它们奴役、拷打、折磨。我因为它们让自己产生了很多烦恼和痛苦，我确实是被它们束缚和捆绑了。感谢世尊，您为我慈悲的说法，不然我还会在这些烦恼和痛苦中煎熬和沉沦。感谢世尊，您给我开出的心药。这个药让我争斗和愤怒的病情开始好转，让我激动的情绪得到了缓解。世尊，我会服下您开出的心药，世尊请您让我皈依您，做您的在家修行弟子吧，我愿意受持您制定的戒律，我愿意按您所说的正法去修行。”</p><p>佛陀接受了这个婆罗门的皈依。</p><p>巴利语原版经文</p>',15)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
